"""Shopping components shared by inventory, saved lists and related listings."""
import html
from urllib.parse import quote

E = lambda v: html.escape(str(v if v is not None else ''), quote=True)

def _t():
    import site_templates
    return site_templates

def _money(n):
    return f'${n:,.0f}' if n else 'Request price'

def _payment(price):
    if not price:
        return None
    rate = .0999 / 12
    return round(price * .8 * rate / (1 - (1 + rate) ** -240))

def card(u, prefix=''):
    t = _t()
    stock = E(u['stock'])
    name = ' '.join(str(u.get(k) or '') for k in ('year', 'brand', 'model', 'floorplan')).strip()
    href = prefix + 'units/' + quote(u['stock'], safe='') + '.html'
    images = list(dict.fromkeys(([u['image']] if u.get('image') else []) + (u.get('images') or [])))[:6]
    slides = ''.join(f'<a class="gallery-slide" href="{href}" tabindex="-1" aria-hidden="true"><img {"src" if i == 0 else "data-src"}="{E(src)}" alt="{E(name)} — photo {i+1}" width="640" height="420" loading="lazy" decoding="async" draggable="false"></a>' for i, src in enumerate(images))
    if not slides:
        image_name = t.TYPE_IMAGES.get(u['type'], 'class_a')
        slides = f'<a class="gallery-slide photo-placeholder" href="{href}"><img src="{prefix}img/types/{image_name}.webp" alt="" width="120" height="60" loading="lazy"><span>Photos coming soon</span></a>'
    controls = ''
    if len(images) > 1:
        controls = f'<button class="gallery-arrow prev" data-card-step="-1" aria-label="Previous photo of {E(name)}">‹</button><button class="gallery-arrow next" data-card-step="1" aria-label="Next photo of {E(name)}">›</button><div class="gallery-dots">' + ''.join(f'<button data-card-dot="{i}" aria-label="Photo {i+1} of {len(images)}" aria-pressed="{str(i==0).lower()}"></button>' for i in range(len(images))) + '</div>'
    badge = ('Just arrived' if u.get('newArrival') else 'New' if u.get('condition') == 'new' else 'Pre-owned') if u['status'] == 'listed' else t.STATUS[u['status']]
    specs = [f'{u["length"]} ft' if u.get('length') else 'Length unlisted', f'Sleeps {u["sleeps"]}' if u.get('sleeps') else 'Ask about sleeping']
    if u.get('slides') is not None:
        specs.append(f'{u["slides"]} slides')
    rows = [('Stock', u['stock']), ('Floorplan', u.get('floorplan')), ('Length', f'{u["length"]} ft' if u.get('length') else None), ('Sleeps', u.get('sleeps')), ('Slideouts', u.get('slides')), ('Fuel', u.get('fuel')), ('Engine', u.get('engine')), ('Chassis', u.get('chassis')), ('Exterior', u.get('exterior')), ('Interior', u.get('interior')), ('Mileage', f'{u["mileage"]:,} mi' if u.get('mileage') is not None else None), ('GVWR', f'{u["gvwr"]:,} lb' if u.get('gvwr') else None)]
    dense = ''.join(f'<div><dt>{k}</dt><dd>{E(v) if v not in (None,"","n/a") else "Not listed"}</dd></div>' for k,v in rows)
    reference = u.get('msrp') if u.get('price') and u.get('msrp', 0) and u['msrp'] > u['price'] else u.get('regularPrice')
    reference_label = 'MSRP' if reference and reference == u.get('msrp') else 'Regular price'
    saving = reference - u['price'] if u.get('price') and reference and reference > u['price'] else 0
    note = f'{reference_label} <s>{_money(reference)}</s>' if saving else 'Confirm current price &amp; availability'
    saved_note = f'<p class="card-savings">Save {_money(saving)} · {saving/reference:.0%} below {reference_label}</p>' if saving else ''
    payment = f'<p class="card-payment"><span data-card-payment>Est. {_money(_payment(u["price"]))}/mo*</span> <button data-edit-finance>View assumptions</button></p>' if u.get('price') else ''
    return f'''<article class="rv-card" data-stock="{stock}" data-card-price="{u.get("price") or ""}"><div class="card-photo"><div class="card-gallery" data-card-gallery tabindex="0" role="region" aria-label="Photos of {E(name)}">{slides}</div>{controls}<span class="status-tag {'pending' if u['status']!='listed' else ''}">{E(badge)}</span><button class="save-button" data-save="{stock}" aria-label="Save {E(name)}" aria-pressed="false">{t.icon('heart')}</button><span class="photo-count">{t.icon('camera')}{u.get('photoCount') or 0}</span></div><div class="card-body"><p class="card-kicker">{E(t.TYPE_NAMES[u['type']])} · {u['year']} · {'New' if u.get('condition')=='new' else 'Pre-owned'}</p><h3 class="card-title"><a href="{href}">{E(u['brand'])} {E(u['model'])} {E(u.get('floorplan'))}</a></h3><div class="card-specs">{''.join('<span>'+E(s)+'</span>' for s in specs)}</div><dl class="card-data-specs">{dense}</dl><div class="card-divider"></div><p class="price-label">Listed price</p><div class="card-price">{_money(u.get('price'))}</div><p class="card-msrp">{note}</p>{saved_note}{payment}<p class="card-location">{t.icon('pin')}{E(u.get('city'))}, {E(u.get('state'))} · #{stock}</p><div class="card-actions"><label class="compare-check"><input type="checkbox" data-compare="{stock}" aria-label="Compare {E(name)}">Compare</label><a class="card-call" href="tel:{E(u.get('phone') or '8003356054')}">Call</a><a class="text-link" href="{href}">Explore this RV {t.icon('arrow')}</a></div></div></article>'''

def filters():
    t = _t()
    opts = lambda values: ''.join(f'<option value="{E(v)}">{E(label)}</option>' for v,label in values)
    return f'''<aside class="filters" id="filters" aria-label="Filter inventory"><div class="filter-heading"><b>Refine your search</b><button data-reset-filters>Reset</button><button class="icon-button filter-close" data-filter-close aria-label="Close filters">{t.icon('close')}</button></div><form class="filter-fields" id="filterForm"><div class="field"><label for="filterCondition">New or pre-owned</label><select name="condition" id="filterCondition"><option value="">Any condition</option><option value="new">New</option><option value="used">Pre-owned</option></select></div><label class="check-field"><input type="checkbox" name="deal">Deals &amp; specials</label><label class="check-field"><input type="checkbox" name="newArrival">New arrivals</label><div class="field"><label for="filterType">RV type</label><select name="type" id="filterType"><option value="">All RV types</option>{opts(t.TYPE_NAMES.items())}</select></div><div class="field"><label for="filterMinPrice">Minimum price</label><input id="filterMinPrice" name="minPrice" type="number" min="0" step="1000" placeholder="No minimum"></div><div class="field"><label for="filterPrice">Maximum price</label><select name="maxPrice" id="filterPrice"><option value="">Any price</option>{opts([(25000,'$25,000'),(50000,'$50,000'),(100000,'$100,000'),(150000,'$150,000'),(175000,'$175,000'),(250000,'$250,000'),(300000,'$300,000'),(400000,'$400,000'),(600000,'$600,000')])}</select></div><div class="field"><label for="filterBrand">Brand</label><select name="brand" id="filterBrand"><option value="">All brands</option></select></div><div class="field"><label for="filterLocation">Location</label><select name="state" id="filterLocation"><option value="">All locations</option><option value="TX">Alvarado, Texas</option><option value="CA">Palm Desert, California</option><option value="AL">Montgomery, Alabama</option></select></div><div class="field"><label for="filterLength">Maximum length</label><select name="maxLength" id="filterLength"><option value="">Any length</option>{opts([(22,'22 ft'),(25,'25 ft'),(30,'30 ft'),(35,'35 ft'),(40,'40 ft')])}</select></div><div class="field"><label for="filterSleeps">Listed sleeping capacity</label><select name="minSleeps" id="filterSleeps"><option value="">Any / not listed</option>{opts([(2,'Sleeps 2+'),(4,'Sleeps 4+'),(6,'Sleeps 6+'),(8,'Sleeps 8+')])}</select></div><div class="field"><label for="filterStatus">Listing status</label><select name="status" id="filterStatus"><option value="">All listing statuses</option><option value="listed">Listed (not pending / on order)</option><option value="pending">Sale pending</option><option value="onorder">On order</option><option value="coming">Coming soon</option></select></div><label class="check-field"><input type="checkbox" name="video">Video available</label><label class="check-field"><input type="checkbox" name="floorplan">Floorplan available</label><p class="filter-note">Missing specifications stay unknown. Confirm current availability and installed equipment with a specialist.</p></form><div class="filter-apply"><button class="button" data-filter-close>Show results {t.icon('arrow')}</button></div></aside>'''

def _conditions():
    return '<div class="shopping-chips" role="group" aria-label="Shop by condition"><button data-quick-condition="all" aria-pressed="true">All RVs</button><button data-quick-condition="new" aria-pressed="false">New</button><button data-quick-condition="used" aria-pressed="false">Pre-owned</button><button data-quick-condition="deal" aria-pressed="false">Deals &amp; specials</button><button data-quick-arrivals aria-pressed="false">Just arrived</button></div>'

def inventory_surface(units,prefix='',heading='Find an RV you’ll love',initial='',total=None):
    t = _t()
    bands=[('','', 'Any budget'),('','50000','Under $50k'),('50000','100000','$50–100k'),('100000','175000','$100–175k'),('175000','300000','$175–300k'),('300000','','$300k+')]
    pills=''.join(f'<button data-price-min="{lo}" data-price-max="{hi}" aria-pressed="{str(not lo and not hi).lower()}">{label}</button>' for lo,hi,label in bands)
    return f'''<section class="inventory-section" id="inventory" data-inventory data-initial-query="{E(initial)}"><div class="container"><div class="inventory-heading"><div><h2 id="inventoryTitle">{heading}</h2><p>Explore the details. Compare your favorites. Make it yours.</p></div><button class="button outline small" data-match>{t.icon('spark')} Help me choose</button></div>{_conditions()}<div class="shopping-chips budget-chips" id="budget" role="group" aria-label="Shop by purchase budget">{pills}</div><details class="payment-assumptions" id="paymentAssumptions"><summary>Payment estimates · view or edit assumptions</summary><p>Illustrative estimates, not a financing offer. Taxes, title, license and fees are excluded. APR and term depend on lender approval, RV age and your qualifications.</p><form id="paymentForm" class="payment-fields"><div class="field"><label for="shoppingApr">APR (%)</label><input id="shoppingApr" name="apr" type="number" min="0" max="35" step="0.01" value="9.99" required></div><div class="field"><label for="shoppingTerm">Term (months)</label><select id="shoppingTerm" name="months"><option value="120">120</option><option value="180">180</option><option value="240" selected>240</option></select></div><div class="field"><label for="shoppingDownPercent">Down payment (%)</label><input id="shoppingDownPercent" name="downPercent" type="number" min="0" max="95" step="1" value="20" required></div><div class="field"><label for="shoppingDownAmount">Or down payment ($)</label><input id="shoppingDownAmount" name="downPayment" type="number" min="0" step="100" placeholder="Use percentage"></div><button type="submit" class="button small">Apply estimates</button></form><p class="payment-note" id="paymentNote">Card estimates use 9.99% APR, 240 months and 20% down. An amount entered in your search overrides this down payment.</p></details><div class="inventory-layout">{filters()}<div><div class="smart-summary" id="smartSummary" hidden></div><div class="results-toolbar"><span class="results-label" id="resultCount" aria-live="polite">{total if total is not None else len(units):,} RVs to explore</span><button class="mobile-filter-button" data-filter-open>{t.icon('filter')} Filters <span id="filterCount"></span></button><div class="shopping-view" role="group" aria-label="Result layout"><button data-shopping-view="visual" aria-pressed="true">Visual</button><button data-shopping-view="data" aria-pressed="false">Data</button></div><label class="sort-select"><span>Sort by</span><select id="sortSelect" aria-label="Sort inventory"><option value="recommended">Recommended</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="savings">Biggest savings</option><option value="year">Newest model year</option><option value="length">Shortest first</option></select></label></div><p class="shopping-view-hint" id="shoppingViewHint" hidden>Data view shows the imported specifications beside each RV. Not listed means the feed did not provide a value.</p><div class="result-grid" id="results">{''.join(card(u,prefix) for u in units[:24])}</div><div class="load-more-row"><small id="resultProgress">Showing {min(24,len(units))} RVs</small><button class="button outline" id="loadMore">Load 24 more {t.icon('arrow')}</button><p class="auto-load-note" id="autoLoadNote">After your first click, more RVs load as you scroll. <button data-auto-load hidden>Pause automatic loading</button></p></div></div></div><div class="concierge-banner"><div class="concierge-symbol">{t.icon('spark')}</div><div><h3>You bring the plans. We'll help find the RV.</h3><p>Answer a few questions and make a shortlist around the way you want to travel.</p></div><button class="button yellow" data-match>Find my RV match {t.icon('arrow')}</button></div></div></section>'''

def home_extras(units,prefix=''):
    return '''<section class="container shopping-discovery"><div id="forYouSection" hidden><div class="section-heading"><div><h2>Picked for you</h2><p id="forYouReason">Based on what you explore on this device.</p></div><button class="reset-button" data-reset-profile>Reset preferences</button></div><div class="discovery-rail" id="forYouRail"></div></div><div class="section-heading"><div><h2 id="featured">Worth a closer look</h2><p>New arrivals, newer model years and savings from the listed MSRP.</p></div><a class="text-link" href="#inventory">Shop all RVs →</a></div><div class="discovery-rail" id="featuredRail"></div><div id="recentSearches" class="recent-searches" hidden><h3>Pick up where you left off</h3><div class="shopping-chips" id="adaptivePrompts"></div></div><div class="section-heading lifestyle-heading"><div><h2>What's your kind of trip?</h2><p>A starting point for your shortlist. Check each RV's layout and equipment.</p></div></div><div class="lifestyle-options"><button data-lifestyle="weekend">Weekend escapes<small>Compact motorhomes &amp; trailers</small></button><button data-lifestyle="family">Family adventures<small>Prioritize listed sleeping space</small></button><button data-lifestyle="fulltime">Full-time living<small>Explore room for everyday life</small></button><button data-lifestyle="adventure">Off-grid &amp; toys<small>Camper vans, toy haulers &amp; Super C</small></button><button class="reset-button" data-lifestyle="">Clear lifestyle</button></div>''' + _conditions() + '</section>'
